// Types for src/data/story.json (generated by scripts/story/build_story.py from the DVD navigation).

export type SceneId = string;
export type ClipId = string;

export interface ClipSource {
  vts: number;
  vob: "title" | "menu";
  firstSector: number;
  lastSector: number;
  cells: string[];
  dvdNode: string;
}

export interface Clip {
  id: ClipId;
  src: string;
  poster: string;
  /** Duration from the DVD IFO cell playback times (seconds). */
  duration: number;
  source: ClipSource;
}

export type ChoiceDirection = "left" | "right" | "down";

export interface Choice {
  id: string;
  label: string;
  original: string;
  direction: ChoiceDirection;
  /** Short confirmation clip the DVD plays only when the viewer actively chooses. */
  stingerClip: ClipId | null;
  target: SceneId;
  isDefault: boolean;
  dvd: { button: number; rect: [number, number, number, number]; command: string; destination: string };
}

interface SceneBase {
  id: SceneId;
  clip: ClipId;
  title: string;
  dvd: { node: string; cells?: string[] };
}

export interface SegmentScene extends SceneBase {
  type: "segment";
  next: SceneId | null;
  endingId?: string;
}

export interface CreditsScene extends SceneBase {
  type: "credits";
  next: SceneId | null;
  endingId: string;
}

export interface DecisionScene extends SceneBase {
  type: "decision";
  index: number;
  prompt: string;
  original: { title: string; prompt: string };
  /** Seconds into the decision clip when the DVD activates its buttons. */
  activeFrom: number;
  /** Seconds into the decision clip when the DVD's timeout (post command) fires. */
  timeout: number;
  defaultChoice: string;
  choices: Choice[];
}

export type Scene = SegmentScene | CreditsScene | DecisionScene;

export interface Ending {
  id: string;
  number: number;
  title: string;
  scene: SceneId;
  credits: SceneId[];
  /** Choice ids (in order) that lead from the opening to this ending. */
  path: string[];
  returnsTo: string;
}

export interface StoryData {
  version: number;
  title: string;
  year: number;
  start: SceneId;
  source: Record<string, string>;
  clips: Record<ClipId, Clip>;
  scenes: Record<SceneId, Scene>;
  decisions: SceneId[];
  endings: Ending[];
}

export interface MediaClipInfo {
  id: string;
  src: string;
  duration: number;
  expectedDuration: number;
  bytes: number;
  width: number;
  height: number;
  fps: string;
  video: string;
  audio: string | null;
  audioChannels: number;
  poster: string;
  sprite: { src: string; interval: number; cols: number; rows: number; count: number; w: number; h: number };
}

export interface MediaManifest {
  clips: Record<ClipId, MediaClipInfo>;
  stills: string[];
}

/** What the player is currently playing. */
export type Step =
  | { kind: "scene"; sceneId: SceneId }
  | { kind: "stinger"; clipId: ClipId; choiceId: string; decisionId: SceneId; then: SceneId };

export interface HistoryEntry {
  decisionId: SceneId;
  choiceId: string;
  timedOut: boolean;
  at: number;
}
